import test from'node:test';import assert from'node:assert/strict';import{browserFormAutomaton,researchBrowserAutomaton,InterpretationRegistry,HostRegistry}from'../src/index.mjs';
test('historical source stays immutable while modern interpretation becomes a new record',()=>{const r=new InterpretationRegistry(),source=r.registerSource({id:'klein-cgc',title:'CGC',mechanism:{tests:['suffix','context']},provenance:'paper'}),modern=r.derive(source.id,{layer:'modern',mappingVersion:'cgc.modern.v1',changes:{typed:true}});assert.notEqual(source.id,modern.id);assert.deepEqual(r.resolve('klein-cgc').mechanism,{tests:['suffix','context']});assert.deepEqual(r.compare(source.id,modern.id).changed,['typed']);assert.throws(()=>r.registerSource({id:'klein-cgc',mechanism:{}}),e=>e.code==='SOURCE_IMMUTABLE');});
test('form filling requires field approval and inferred confirmation',async()=>{const b=browserFormAutomaton();await b.call({operation:'inspect-page',page:{url:'https://agency.gov',forms:[{id:'f',action:'https://agency.gov/submit',official:true,fields:[{name:'name',required:true},{name:'ssn',required:true}]}]}});const d=await b.call({operation:'draft',formId:'f',values:{name:'A',ssn:'123'},context:{sources:{name:{kind:'entered'},ssn:{kind:'inferred'}}}});assert.rejects(()=>b.call({operation:'fill',draftId:d.id}),e=>e.code==='FIELD_APPROVAL_REQUIRED');await b.call({operation:'approve-fields',draftId:d.id,names:['name']});await b.call({operation:'confirm-inferred',draftId:d.id,names:['ssn']});assert.equal((await b.call({operation:'fill',draftId:d.id})).status,'filled');});
test('submission is impossible without separate final confirmation and mounted executor',async()=>{const state=(await import('../src/browser-form.mjs')).BrowserFormState;const s=new state();s.inspectPage({url:'x',forms:[{id:'f',action:'submit',fields:[{name:'x',required:true}]}]});const d=s.createDraft('f',{x:'1'},{sources:{x:{kind:'entered'}}});s.approveFields(d.id,['x']);s.fill(d.id);const req=s.requestSubmission(d.id);assert.throws(()=>s.submit(req.id,()=>true),e=>e.code==='SUBMISSION_CONFIRMATION_REQUIRED');s.confirmSubmission(req.id);assert.equal(s.submit(req.id,()=>({ok:true})).ok,true);});
test('research browser preserves source, claim, experiment, and bibliography lineage',async()=>{const r=researchBrowserAutomaton();const p=await r.call({operation:'create',project:{id:'p',title:'Study',question:'Does it work?'}});const source=await r.call({operation:'source',projectId:p.id,source:{id:'s1',url:'https://source',title:'Paper'}});const claim=await r.call({operation:'claim',projectId:p.id,claim:{id:'c1',text:'Observed result',sourceIds:[source.id]}});await r.call({operation:'hypothesis',projectId:p.id,hypothesis:{id:'h1',statement:'It works',evidenceClaimIds:[claim.id]}});await r.call({operation:'experiment',projectId:p.id,experiment:{id:'e1',hypothesisId:'h1',protocol:{requiredCapabilities:['execute-code']},effects:['local-compute']}});const draft=await r.call({operation:'draft',projectId:p.id,draft:{title:'Report',sections:[{heading:'Finding',claimIds:['c1']}]}});assert.equal(draft.sections[0].content[0],'Observed result[s1]');assert.equal(draft.bibliography[0].url,'https://source');});
